import numpy as np
f=np.load('source_pixels.npz')['rgb'].astype(float)
# initial velocities via robust HSV centroid, expected color centroid shifts. fit x positions early
import cv2
from scipy.ndimage import label
for name in ['R','Y']:
 pts=[]
 for i in range(16):
  hsv=cv2.cvtColor(f[i].astype('uint8'),cv2.COLOR_RGB2HSV);h,s,v=hsv[:,:,0],hsv[:,:,1],hsv[:,:,2]
  if name=='R': mask=((h>158)|(h<5))&(s>70)&(v>100)
  else: mask=(h>20)&(h<50)&(s>70)&(v>90)
  lab,n=label(mask); cs=[]
  for j in range(1,n+1):
   yy,xx=np.where(lab==j)
   if len(xx)>=3 and ((name=='R' and xx.mean()<105) or (name=='Y' and xx.mean()>165)):
    cs.append((len(xx),xx.mean(),yy.mean()))
  if cs: pts.append((i,*max(cs)[1:]))
 print(name,pts)
 co=np.polyfit([p[0] for p in pts],[p[1] for p in pts],1)
 co2=np.polyfit([p[0] for p in pts],[p[2] for p in pts],1)
 print('fit x',co,'y',co2)
PY"

