import numpy as np
from PIL import Image
f=np.load('source_pixels.npz')['rgb'].astype(np.float32)
N,H,W,_=f.shape
mask=np.zeros((N,H,W),bool)
for i in range(N):
    if i<=32: r=(47+1.97*i,66+0.13*i)
    elif i<40:
        t=(i-32)/6; r=(112+0.8*t,73)
    else: r=(113+0.7*(i-40)/55,73.2)
    if i<=33: y=(214-2.25*i,76.3-0.145*i)
    elif i<40:
        t=(i-33)/5; y=(141+0.5*t,72)
    else: y=(141.5+0.3*(i-40)/55,72.2)
    for cx,cy in (r,y):
        x0=max(0,int(np.floor(cx))-10);x1=min(W,int(np.ceil(cx))+11)
        y0=max(0,int(np.floor(cy))-8);y1=min(H,int(np.ceil(cy))+9)
